 * This class allows modifications to the default sanitizer configuration.
 * It builds an instance of `HtmlSanitizer`.
 */
export declare class HtmlSanitizerBuilder extends BaseSanitizerBuilder<HtmlSanitizer> {
    build(): HtmlSanitizer;
}
