11	 * An HTML5-compliant markup sanitizer that produces SafeHtml markup.
12	 *
13	 * You can build sanitizers with a custom configuration using the
14	 * HtmlSanitizerBuilder.
15	 */
16	export interface HtmlSanitizer {
