:root {
  color-scheme: light dark;
  --bg: #f6f7f9;
  --surface: #ffffff;
  --border: #d7dce3;
  --text: #16202b;
  --muted: #5a6672;
  --accent: #0f766e;
  --accent-soft: #e3f2f0;
  --focus: #0b5fa4;
  --radius: 10px;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #11161c;
    --surface: #182029;
    --border: #2c3743;
    --text: #e7edf3;
    --muted: #9aa7b4;
    --accent: #4dd6c5;
    --accent-soft: #16302e;
    --focus: #7bb8ff;
  }
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  padding: 1.5rem 1rem 4rem;
  background: var(--bg);
  color: var(--text);
  font: 16px/1.55 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
}

#app {
  max-width: 44rem;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.app-header h1 {
  margin: 0;
  font-size: 1.75rem;
  letter-spacing: -0.01em;
}

.app-tagline {
  margin: 0.25rem 0 0;
  color: var(--muted);
}

.panel {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1rem 1.125rem 1.25rem;
}

.panel h2 {
  margin: 0 0 0.75rem;
  font-size: 1.05rem;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
  margin-bottom: 0.85rem;
}

label {
  font-weight: 600;
  font-size: 0.9rem;
}

.optional {
  font-weight: 400;
  color: var(--muted);
}

input,
textarea,
button {
  font: inherit;
  color: inherit;
}

input,
textarea {
  padding: 0.5rem 0.65rem;
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: 8px;
}

textarea {
  resize: vertical;
  min-height: 5.5rem;
}

.hint {
  margin: 0;
  font-size: 0.8rem;
  color: var(--muted);
}

button.primary {
  padding: 0.55rem 1.1rem;
  background: var(--accent);
  color: #ffffff;
  border: 1px solid transparent;
  border-radius: 8px;
  font-weight: 600;
  cursor: pointer;
}

@media (prefers-color-scheme: dark) {
  button.primary {
    color: #0b1418;
  }
}

button.primary:hover {
  filter: brightness(1.08);
}

:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

#results-line {
  margin: 0.25rem 0 0;
  min-height: 1.25rem;
  color: var(--muted);
  font-size: 0.9rem;
}

#feed {
  display: flex;
  flex-direction: column;
  gap: 0.85rem;
}

.note {
  background: var(--surface);
  border: 1px solid var(--border);
  border-left: 4px solid transparent;
  border-radius: var(--radius);
  padding: 0.9rem 1.125rem 1rem;
}

.note[aria-current="true"] {
  border-left-color: var(--accent);
  background: var(--accent-soft);
}

.note-header {
  display: flex;
  align-items: center;
  gap: 0.7rem;
}

.note-avatar {
  width: 40px;
  height: 40px;
  flex: none;
  border-radius: 50%;
  object-fit: cover;
  background: var(--bg);
}

.note-heading {
  margin: 0;
  font-size: 1.1rem;
  min-width: 0;
}

.note-title {
  padding: 0;
  background: none;
  border: 0;
  font: inherit;
  text-align: left;
  color: inherit;
  cursor: pointer;
}

.note-title:hover {
  text-decoration: underline;
}

.note-body {
  margin-top: 0.5rem;
  overflow-wrap: anywhere;
}

.note-body a,
.note-title a {
  color: var(--focus);
}

.note-date {
  display: block;
  margin-top: 0.6rem;
  font-size: 0.78rem;
  color: var(--muted);
}

.feed-empty {
  margin: 0;
  padding: 1.25rem;
  border: 1px dashed var(--border);
  border-radius: var(--radius);
  color: var(--muted);
  text-align: center;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

