import { chromium } from 'playwright-core';
import fs from 'node:fs';

const browser = await chromium.launch({ args: ['--no-sandbox'] });
const page = await browser.newPage();
const errors = [];
page.on('pageerror', (e) => errors.push(String(e)));
page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });

await page.goto('http://127.0.0.1:4321/');
await page.waitForSelector('#feed article.note');

// golden path: add a note with rich text + avatar
await page.fill('#title', 'Smoke test note');
await page.fill('#body', 'Hello <b>world</b>\nSecond line with <a href="https://example.com">a link</a>.');
await page.fill('#avatar', 'https://example.com/avatar.png');
await page.click('#note-form button[type=submit]');
await page.waitForSelector('article.note:has-text("Smoke test note")');

const bodyHtml = await page.locator('article.note:has-text("Smoke test note") .note-body').innerHTML();
console.log('BODY HTML:', bodyHtml);

// search
await page.fill('#search', 'douro');
await page.waitForSelector('#results-line:has-text(\'results for "douro"\')');
const feedCount = await page.locator('#feed article.note').count();
console.log('Feed count for "douro":', feedCount);

// select a note -> deep link
await page.click('#feed article.note .note-title >> nth=0');
const hash1 = await page.evaluate(() => location.hash);
console.log('Hash after select:', hash1);

// reload and check restore
await page.reload();
await page.waitForSelector('#feed article.note');
const searchVal = await page.inputValue('#search');
