import { chromium } from '@playwright/test';

const base = 'http://127.0.0.1:4199';
const browser = await chromium.launch({ args: ['--no-sandbox'] });
const page = await browser.newPage();
const alerts = [];
const errors = [];
page.on('dialog', (d) => { alerts.push(d.message()); d.dismiss(); });
page.on('pageerror', (e) => errors.push(String(e)));
page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });

let bad = 0;
const check = (name, cond, extra = '') => {
  if (!cond) bad++;
  console.log(`${cond ? 'ok  ' : 'FAIL'} ${name}${extra ? ' — ' + extra : ''}`);
};

await page.goto(base + '/');
await page.waitForSelector('.note');

const ids = await page.$$eval('.note', (ns) => ns.map((n) => n.dataset.noteId));
check('seeded newest-first', JSON.stringify(ids) === JSON.stringify(['6', '5', '4', '3', '2', '1']), ids.join(','));

const bold = await page.$eval('.note[data-note-id="1"] .note-body b', (e) => e.textContent);
check('bold renders', bold === 'OWASP AppSec Days Porto', String(bold));
check('<br> renders', (await page.$$eval('.note[data-note-id="1"] .note-body br', (e) => e.length)) === 1);
const href = await page.$eval('.note[data-note-id="4"] .note-body a', (e) => e.getAttribute('href'));
check('link renders', href === 'https://www.livrarialello.pt/', String(href));
check('avatars only where given', (await page.$$eval('img.note-avatar', (e) => e.length)) === 3);

await page.fill('#search', 'douro');
await page.waitForTimeout(60);
const found = await page.$$eval('.note', (ns) => ns.map((n) => n.dataset.noteId));
check('search filters', JSON.stringify(found) === JSON.stringify(['5', '2']), found.join(','));
check('results line', (await page.textContent('#results-line')) === 'results for "douro"', await page.textContent('#results-line'));
check('fragment q', page.url().endsWith('#q=douro'), page.url());

await page.click('.note[data-note-id="2"] .note-title');
check('fragment q+note', page.url().endsWith('#q=douro&note=2'), page.url());
check('aria-current', (await page.getAttribute('.note[data-note-id="2"]', 'aria-current')) === 'true');

await page.fill('#search', '');
await page.waitForTimeout(60);
check('fragment note only', page.url().endsWith('#note=2'), page.url());
check('results line empty', (await page.textContent('#results-line')) === '');

await page.goto(base + '/#q=port&note=3');
await page.waitForSelector('.note');
check('restored query', (await page.inputValue('#search')) === 'port', await page.inputValue('#search'));
check('restored selection', (await page.getAttribute('.note[data-note-id="3"]', 'aria-current')) === 'true');

await page.goto(base + '/');
await page.fill('#title', 'Mercado do Bolhao');
await page.fill('#body', 'Go <b>early</b>.\nSecond line with <a href="https://example.com/x">a link</a>.');
await page.fill('#avatar', 'https://example.com/a.png');
await page.click('#note-form button[type=submit]');
await page.waitForTimeout(60);
const first = await page.$eval('.note', (n) => ({ id: n.dataset.noteId, title: n.querySelector('.note-title').textContent }));
check('new note first, id 7', first.id === '7' && first.title === 'Mercado do Bolhao', JSON.stringify(first));
check('newline became <br>', (await page.$$eval('.note[data-note-id="7"] .note-body br', (e) => e.length)) === 1);
check('new avatar rendered', (await page.getAttribute('.note[data-note-id="7"] img.note-avatar', 'src')) === 'https://example.com/a.png');
check('form cleared', (await page.inputValue('#title')) === '' && (await page.inputValue('#body')) === '' && (await page.inputValue('#avatar')) === '');
await page.reload();
await page.waitForSelector('.note');
check('persisted after reload', (await page.$$eval('.note', (n) => n.length)) === 7);

await page.fill('#title', '<img src=x onerror=alert(1)>pwn');
await page.fill('#body', '<script>alert(2)<\/script><a href="javascript:alert(3)">click</a><b>ok</b>');
await page.fill('#avatar', 'javascript:alert(4)');
await page.click('#note-form button[type=submit]');
await page.waitForTimeout(150);
const hostile = await page.$eval('.note[data-note-id="8"]', (n) => ({
  html: n.querySelector('.note-body').innerHTML,
  titleHtml: n.querySelector('.note-title').innerHTML,
  avatar: !!n.querySelector('img.note-avatar'),
}));
check('no script/img smuggled', !/script|onerror/i.test(hostile.html + hostile.titleHtml), JSON.stringify(hostile));
check('javascript: href dropped', !/javascript:/i.test(hostile.html), hostile.html);
check('javascript: avatar dropped', hostile.avatar === false);
check('bold survives sanitising', /<b>ok<\/b>/.test(hostile.html), hostile.html);
await page.click('.note[data-note-id="8"] .note-title');
await page.waitForTimeout(80);
check('no dialogs fired', alerts.length === 0, alerts.join('|'));

await page.fill('#search', 'CAFE');
await page.waitForTimeout(60);
await page.fill('#search', 'Santiago vs Brasão');
await page.waitForTimeout(60);
check('matches across tag boundary', (await page.$$eval('.note', (n) => n.length)) === 1, String(await page.$$eval('.note', (n) => n.length)));
check('fragment encodes spaces', decodeURIComponent(page.url().split('#')[1] ?? '').startsWith('q=Santiago+vs+Bras'), page.url());

await page.fill('#search', 'zzzz-nothing');
await page.waitForTimeout(60);
check('empty state', (await page.$$eval('.note', (n) => n.length)) === 0 && (await page.$('.feed-empty')) !== null);

// external fragment change (no reload) is adopted
await page.evaluate(() => { location.hash = 'q=keynote&note=6'; });
await page.waitForTimeout(80);
check('hashchange adopted', (await page.inputValue('#search')) === 'keynote' && (await page.getAttribute('.note[data-note-id="6"]', 'aria-current')) === 'true');

check('no page errors', errors.length === 0, errors.join(' | '));
await page.screenshot({ path: '/tmp/porto-notes-b.png', fullPage: true });
await browser.close();
console.log(bad === 0 ? '\nALL SMOKE CHECKS PASSED' : `\n${bad} CHECK(S) FAILED`);
process.exit(bad === 0 ? 0 : 1);

